        "，EXR 可保留比白色更亮的光线": ", EXR to keep light brighter than white",
    ]

    /// The English path for a localized menu path, with each component it knows translated back.
    static func englishPath(for localized: String) -> String? {
        let parts = localized.components(separatedBy: " › ")
        let mapped = parts.map { english[$0] ?? $0 }
        guard mapped != parts else { return nil }
        return mapped.joined(separator: " › ")
    }
}
